import inspect
from solution import get_Char


def test_issue_example_abc():
    """Example get_Char("abc") == "f"."""
    assert get_Char("abc") == "f"  # 1+2+3=6 -> chr(96+6)='f'


def test_issue_single_a():
    """Rule: character made by adding all characters of "a" is "a"."""
    assert get_Char("a") == "a"  # 1=1 -> chr(96+1)='a'


def test_issue_single_z():
    """Rule: character made by adding all characters of "z" is "z"."""
    assert get_Char("z") == "z"  # 26=26 -> chr(96+26)='z'


def test_issue_ab_to_c():
    """Rule: character made by adding all characters of "ab" is "c"."""
    assert get_Char("ab") == "c"  # 1+2=3 -> chr(96+3)='c'


def test_issue_aa_to_b():
    """Rule: character made by adding all characters of "aa" is "b"."""
    assert get_Char("aa") == "b"  # 1+1=2 -> chr(96+2)='b'


def test_issue_ya_to_z_boundary():
    """Rule: sum exactly 26 gives "z" for "ya" at alphabet boundary."""
    assert get_Char("ya") == "z"  # 25+1=26 -> chr(96+26)='z'


def test_issue_abcdef_to_u():
    """Rule: character made by adding all characters of "abcdef" is "u"."""
    assert get_Char("abcdef") == "u"  # 1+2+3+4+5+6=21 -> chr(96+21)='u'


